mapper.select:
SELECT p.id AS id, p.merchant_id AS merchantId, m.shop_name AS shopName, u.username AS userName, p.category_id AS categoryId, c.name AS categoryName, p.name AS name, p.price AS price, p.stock AS stock, p.image AS image, p.description AS description, p.status AS status, p.audit_status AS auditStatus, p.create_time AS createTime, p.update_time AS updateTime FROM product p LEFT JOIN merchant m ON m.user_id = p.merchant_id LEFT JOIN user u ON u.id = p.merchant_id LEFT JOIN category c ON c.id = p.category_id
AND p.audit_status = #{query.auditStatus}
AND p.name LIKE CONCAT('%', #{query.keyword}, '%')
ORDER BY p.audit_status ASC, p.create_time DESC, p.id DESC
LIMIT #{query.page}, #{query.size}

SELECT COUNT(*) FROM product p
AND p.audit_status = #{query.auditStatus}
AND p.name LIKE CONCAT('%', #{query.keyword}, '%')
